{
  "$schema": "https://turborepo.dev/schema.json",
  "globalDependencies": [".env", "tsconfig.base.json"],
  "globalEnv": ["NODE_ENV"],
  "tasks": {
    "build": {
      "dependsOn": ["^build"],
      "inputs": ["$TURBO_DEFAULT$", ".env*"],
      "outputs": ["dist/**", ".next/**", "!.next/cache/**"],
      "env": ["NEXT_PUBLIC_API_URL"]
    },
    "test": {
      "dependsOn": ["build"],
      "outputs": ["coverage/**"]
    },
    "dev": {
      "cache": false,
      "persistent": true
    }
  }
}

{
  "extends": ["//"],
  "tasks": {
    "build": {
      "outputs": ["$TURBO_EXTENDS$", ".next/**", "!.next/cache/**"]
    }
  }
}

{
  "$schema": "https://turborepo.dev/schema.json",
  "ui": "tui",
  "concurrency": "50%",
  "envMode": "strict",
  "cacheDir": ".turbo/cache",
  "cacheMaxSize": "10GB",
  "remoteCache": {
    "signature": true
  }
}

{
  "$schema": "https://turborepo.dev/schema.json",
  "tasks": {
    "lint": {},
    "build": {
      "dependsOn": ["^build", "lint"]
    },
    "test": {
      "dependsOn": ["build"]
    },
    "web#deploy": {
      "dependsOn": ["test", "@acme/ui#build"]
    }
  }
}

{
  "extends": ["//"],
  "tasks": {
    "dev": {
      "with": ["api#dev"],
      "persistent": true,
      "cache": false
    }
  }
}

{
  "tasks": {
    "build": {
      "inputs": ["$TURBO_DEFAULT$", "!README.md", ".env.production"],
      "outputs": ["dist/**", "!.next/cache/**"],
      "outputLogs": "new-only"
    },
    "typecheck": {
      "inputs": ["$TURBO_DEFAULT$", "$TURBO_ROOT$/tsconfig.base.json"],
      "outputs": []
    }
  }
}

{
  "remoteCache": {
    "enabled": true,
    "signature": true,
    "timeout": 30,
    "uploadTimeout": 60,
    "apiUrl": "https://cache.acme.dev"
  }
}

{
  "globalEnv": ["NODE_ENV"],
  "globalPassThroughEnv": ["GITHUB_TOKEN"],
  "envMode": "strict",
  "tasks": {
    "build": {
      "env": ["DATABASE_URL", "STRIPE_*", "!STRIPE_TEST_KEY"],
      "passThroughEnv": ["SENTRY_AUTH_TOKEN"]
    }
  }
}

{
  "globalDependencies": [".env"],
  "tasks": {
    "build": {
      "inputs": [
        "$TURBO_DEFAULT$",
        ".env.production.local",
        ".env.production"
      ]
    }
  }
}

{
  "private": true,
  "scripts": {
    "build": "turbo run build",
    "dev": "turbo run dev",
    "lint": "turbo run lint",
    "test": "turbo run test"
  },
  "devDependencies": {
    "turbo": "2.11.5"
  },
  "devEngines": {
    "packageManager": {
      "name": "pnpm",
      "version": "9.0.0"
    }
  }
}
